import { renderPriceSetup } from './price-setup.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const number=value=>{
  if(typeof value!=='number'||!Number.isFinite(value))return 'Unavailable';
  const magnitude=Math.abs(value);
  return new Intl.NumberFormat('en-US',magnitude!==0&&(magnitude<0.0001||magnitude>=1e9)?{notation:'scientific',maximumSignificantDigits:6}:{maximumFractionDigits:4}).format(value);
};
const exactPrice=value=>typeof value==='string'&&/^\d{1,15}(?:\.\d{1,12})?$/.test(value)&&/[1-9]/.test(value)?value:'Unavailable';
const headlinePrice=value=>exactPrice(value).split('.').map(part=>part.replace(/(\d{3})(?=\d)/g,'$1<wbr>')).join('.<wbr>');
const https=value=>{try{const url=new URL(value);return url.protocol==='https:'?url.href:null;}catch{return null;}};
const stamp=value=>typeof value==='string'&&Number.isFinite(Date.parse(value))?new Date(value).toISOString().replace('T',' ').replace('.000Z','Z').replace(/Z$/,' UTC'):'Unavailable';
const words=value=>String(value??'Unavailable').replaceAll('_',' ');
const external=(url,label)=>https(url)?`<a href="${escape(https(url))}" target="_blank" rel="noopener noreferrer">${escape(label)}<span class="sr-only"> (opens in a new tab)</span> <span aria-hidden="true">↗</span></a>`:'<span>Source link unavailable</span>';
const rows=values=>`<dl class="desk-facts">${values.map(([label,value])=>`<div><dt>${escape(label)}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl>`;
const days=count=>`${count} trading day${count===1?'':'s'}`;
// Names the control that produced the outcome line, as desk-tools.js records it.
const anchorOf=(...parts)=>parts.map(part=>encodeURIComponent(String(part))).join(':');
const pageAnchors=[anchorOf('form','selection'),anchorOf('action','load-hosted'),anchorOf('form','import')];
const missingDays=count=>`${count} expected trading day${count===1?' is':'s are'} missing.`;
// Plain words for the codes the price logic returns. An unknown code still shows, as words.
const plainCode=(map,fallback)=>code=>typeof code==='string'&&Object.hasOwn(map,code)?map[code]:fallback(code);
const basis=plainCode({unadjusted:'Not adjusted for splits or dividends',split_adjusted:'Adjusted for splits',total_return_adjusted:'Adjusted for splits and dividends',unknown:'Adjustment unknown'},words);
const warning=plainCode({bars_missing:'The file has no trading days for this company.',volume_missing:'Volume is missing for at least one trading day.',capture_provenance_incomplete:'The source link, capture time or file fingerprint is missing.',capture_in_future:'The capture time is later than now.',adjustment_status_unknown:'The file does not say whether prices were adjusted for splits or dividends.',corporate_action_coverage_unknown:'The file does not confirm every split and dividend.',manual_import_unreviewed:'You imported this file by hand. Nobody has reviewed it.',pagination_incomplete:'The source download is incomplete.',unsupported_corporate_action:'The file lists an event type the app does not read. It reads only splits and cash dividends.',calendar_unverified:'No verified trading calendar is loaded.',trading_sessions_missing:'Some expected trading days are missing.',capture_stale:'The capture is older than the allowed age.',completed_session_missing:'The latest completed trading day is missing.',account_entitlement_not_verified:'Nobody has checked what your data plan allows.',daily_ohlc_paper_proxy_not_executable_fill:'Daily prices are reference prices. Nobody promises you could trade at them.',provider_adjustment_not_total_return:'The provider adjusted these prices in its own way. The app treats the price basis as unknown.'},words);
const comparisonReason=plainCode({benchmark_missing:'No benchmark prices are loaded.',benchmark_invalid:'The benchmark prices did not pass the file checks.',benchmark_capture_in_future:'The benchmark capture time is later than now.',benchmark_basis_mismatch:'The benchmark uses a different currency, time zone or price basis.',adjustment_basis_unknown:'The file does not say whether prices were adjusted for splits or dividends.',benchmark_sessions_mismatch:'The two series need the same trading days, with at least two days.',benchmark_session_gaps:'A series is missing expected trading days.',unadjusted_action_capture_in_future:'A split and dividend record has a capture time later than now.',unadjusted_action_comparison_withheld:'These prices are not adjusted for splits or dividends. A comparison needs complete split and dividend records that show none in these dates.',comparison_arithmetic_invalid:'The index values could not be calculated.',price_series_unavailable:'The price series is unavailable.'},code=>`Reason: ${words(code)}.`);

function chart(points,currency,symbol){
  const min=Math.min(...points.map(point=>point.low)),max=Math.max(...points.map(point=>point.high));
  const spread=max-min||Math.max(Math.abs(max)*.01,1),floor=min===max?min-spread/2:min;
  const x=index=>points.length===1?360:12+index/(points.length-1)*696;
  const y=value=>224-(value-floor)/spread*208;
  const segments=[];let segment=[];
  for(let index=0;index<points.length;index++){
    if(points[index].breakBefore&&segment.length){segments.push(segment);segment=[];}
    segment.push(`${x(index).toFixed(2)},${y(points[index].close).toFixed(2)}`);
  }
  if(segment.length)segments.push(segment);
  const title=`${symbol} approximate daily closing-price plot`,description=`${days(points.length)}, ${points[0].session} through ${points.at(-1).session}. ${currency} prices. Breaks mark missing trading days or corporate actions. Plot positions and axis labels are approximate. Supplied decimal prices follow in the data table.`;
  return `<figure class="price-figure"><div class="price-plot-layout"><div class="price-axis" aria-hidden="true"><span>${escape(number(max))}</span><span>${escape(number((max+min)/2))}</span><span>${escape(number(min))}</span></div><svg class="price-plot" viewBox="0 0 720 240" preserveAspectRatio="none" role="img" aria-labelledby="price-plot-title price-plot-description"><title id="price-plot-title">${escape(title)}</title><desc id="price-plot-description">${escape(description)}</desc><path class="price-grid" d="M0 16H720 M0 120H720 M0 224H720"/>${segments.map(segment=>segment.length===1?`<path class="price-line" d="M${segment[0]}h.1"/>`:`<polyline class="price-line" points="${segment.join(' ')}"/>`).join('')}</svg></div><div class="price-date-axis" aria-hidden="true"><span>${escape(points[0].session)}</span><span>${escape(points.at(-1).session)}</span></div><figcaption>Approximate daily close · ${escape(currency)} · ${days(points.length)}</figcaption></figure>`;
}

function priceTable(points,currency,retained=false){
  return `<details class="desk-disclosure" data-state-key="prices:daily-values"><summary>Daily prices and volume</summary><div class="desk-table-scroll" tabindex="0" role="region" aria-label="Daily price values, scroll horizontally if needed"><table class="desk-table"><caption>${retained?'Retained':'Imported'} daily values · ${escape(currency)}</caption><thead><tr><th scope="col">Trading day</th><th scope="col">Open</th><th scope="col">High</th><th scope="col">Low</th><th scope="col">Close</th><th scope="col">Volume</th><th scope="col">Notes</th></tr></thead><tbody>${points.map(point=>`<tr><th scope="row">${escape(point.session)}</th>${['open','high','low','close'].map(key=>`<td>${escape(exactPrice(point.decimals?.[key]))}</td>`).join('')}<td>${escape(number(point.volume))}</td><td>${point.breakBefore?'Gap before this trading day. ':''}${Array.isArray(point.actions)&&point.actions.length?`${point.actions.length} corporate action${point.actions.length===1?'':'s'} recorded.`:''}</td></tr>`).join('')}</tbody></table></div></details>`;
}

function comparisonView(comparison,symbol){
  const available=comparison?.status==='available'&&Array.isArray(comparison.points)&&comparison.points.length>0&&comparison.points.every(point=>point&&Number.isFinite(point.targetIndex)&&Number.isFinite(point.benchmarkIndex));
  return `<details class="desk-disclosure" data-state-key="prices:comparison"><summary>Benchmark comparison</summary>${available?`<p>Indexed to 100 on the first shared trading day. Both series use the same dates, currency and price basis. Displayed index values are approximate. This describes the supplied history.</p><div class="desk-table-scroll" tabindex="0" role="region" aria-label="Indexed price comparison"><table class="desk-table"><caption>${escape(symbol)} and ${escape(comparison.benchmarkSymbol)} · ${escape(words(comparison.basis))}</caption><thead><tr><th scope="col">Trading day</th><th scope="col">${escape(symbol)}</th><th scope="col">${escape(comparison.benchmarkSymbol)}</th></tr></thead><tbody>${comparison.points.map(point=>`<tr><th scope="row">${escape(point.session)}</th><td>${escape(number(point.targetIndex))}</td><td>${escape(number(point.benchmarkIndex))}</td></tr>`).join('')}</tbody></table></div>`:`<p>Comparable benchmark history is unavailable.${comparison?.reason?` ${escape(comparisonReason(comparison.reason))}`:''}</p>`}</details>`;
}

/** Pure view. The host owns imports, selected symbols and the isolated widget.
 * options.symbolOptions: [{symbol,label}]; hosted: {status,url,symbol,message}.
 * feedbackAnchor: optional id of the control that produced the feedback ("form:selection",
 * "action:load-hosted" or "form:import"). The line then renders right after that control,
 * static and without tabindex. null keeps every render exactly as before.
 * rosterNote: optional plain sentence under the picker that says which companies it covers.
 * Imported bars never establish evaluated prices or paper marks.
 */
export function renderPriceView(model=null,{symbol=model?.symbol||'',rangeSessions=20,symbolOptions=[],hosted={status:'idle'},feedback=null,priceSetup,feedbackAnchor=null,rosterNote=null}={}){
  const available=!!model&&['available','partial'].includes(model.status)&&Array.isArray(model.points)&&model.points.length>0&&model.points.every(point=>point&&['open','high','low','close'].every(key=>typeof point[key]==='number'&&Number.isFinite(point[key]))&&typeof point.session==='string');
  const points=available?model.points:[],source=model?.source||{},freshness=model?.freshness||{},currency=model?.currency||'Currency unavailable';
  const capture={within_policy:'Within the capture-age policy',stale:'Source capture is stale',unknown:'Capture age unavailable',invalid:'Capture clock invalid'}[freshness.captureStatus]||'Capture age unavailable';
  const session={current_completed_session:'Latest completed trading day included',behind_completed_session:'Latest completed trading day missing',calendar_unknown:'Trading-day coverage unknown'}[freshness.sessionStatus]||'Trading-day coverage unknown';
  const choices=symbolOptions.length?symbolOptions:symbol?[{symbol,label:symbol}]:[];
  const retained=source.channel==='retained_capture';
  const providerURL=https(hosted.url)||'https://www.tradingview.com/chart/';
  // The picker, the chart box and the import form are always on this page, so an anchored line always
  // has its place. The chart replaces the load button inside its box (desk-tools mount()), so that line
  // stands where the button stood, just above the box. Without an anchor the line stays at the top.
  const inline=feedback&&pageAnchors.includes(feedbackAnchor)?feedbackAnchor:null;
  const line=anchor=>inline===anchor?`<p class="desk-feedback desk-feedback-inline">${escape(feedback)}</p>`:'';
  return `<div class="price-desk utility-desk">
    <p class="price-lede">Charts and imported prices are for viewing only. The journal never uses them.</p>
    <section class="desk-controls card" aria-label="Price chart selection"><form data-price-form="selection" class="desk-selection"><label for="price-symbol">Company<select id="price-symbol" name="symbol">${choices.map(choice=>`<option value="${escape(choice.symbol)}"${choice.symbol===symbol?' selected':''}>${escape(choice.label||choice.symbol)}</option>`).join('')}</select></label><label for="price-range">Imported days to show<select id="price-range" name="rangeSessions">${[20,60,120,'all'].map(range=>`<option value="${range}"${String(range)===String(rangeSessions)?' selected':''}>${range==='all'?'All days in the file':`${range} trading days`}</option>`).join('')}</select></label><button class="desk-button desk-button-secondary" type="submit">Apply</button></form>${line(anchorOf('form','selection'))}${typeof rosterNote==='string'&&rosterNote.trim()?`<p class="desk-roster-note">${escape(rosterNote.trim())}</p>`:''}</section>
    ${feedback&&!inline?`<p class="desk-feedback" tabindex="0">${escape(feedback)}</p>`:''}
    <section class="card desk-panel hosted-price-panel" aria-labelledby="hosted-price-heading"><div class="desk-panel-heading"><div><span class="eyebrow">Market chart</span><h2 id="hosted-price-heading" tabindex="-1" data-focus-fallback>${escape(symbol||'Company')} chart</h2></div><span class="desk-badge">TradingView</span></div><p>This chart loads from TradingView, a separate site, only when you ask.</p>${line(anchorOf('action','load-hosted'))}<div id="hosted-price-chart" class="hosted-price-chart" data-hosted-status="${escape(hosted.status||'idle')}">${hosted.status==='ready'?'<p class="desk-muted">Hosted chart is ready.</p>':hosted.status==='loading'?'<p role="status">Loading the hosted chart…</p>':`<div class="desk-empty">${hosted.status==='unavailable'?`<p>${escape(hosted.message||'The hosted chart could not be loaded.')}</p>`:''}${hosted.url===null?`<p>Cribscore has no TradingView chart for ${escape(symbol||'this company')}.</p>`:`<button class="desk-button" type="button" data-price-action="load-hosted">${hosted.status==='unavailable'?'Try the chart again':symbol?`Load ${escape(symbol)} chart`:'Load chart'}</button>`}</div>`}</div><p class="desk-source">${external(providerURL,'Open chart at TradingView')} <span>Prices may be delayed. For NYSE and Nasdaq stocks, TradingView shows Cboe One data (prices from Cboe’s own stock exchanges only).</span></p></section>
    <section class="card desk-panel" aria-labelledby="imported-price-heading"><div class="desk-panel-heading"><div><span class="eyebrow">${retained?'Server capture':'Your price file'}</span><h2 id="imported-price-heading">${retained?'Retained':'Imported'} daily prices</h2></div>${available?`<span class="desk-badge">${escape(basis(model.priceBasis))}</span>`:''}</div>
      ${available?`<div class="price-value"><strong>${headlinePrice(points.at(-1).decimals?.close)}</strong><span>${escape(currency)} · close on ${escape(points.at(-1).session)}</span></div><p class="desk-notice">This dataset has not been verified for journal valuation. Paper marks remain unavailable. Paper marks are the checked prices the journal uses to value practice trades.</p><div class="price-status-line"><span>${escape(capture)}</span><span>${escape(session)}</span></div>${chart(points,currency,symbol||model.symbol)}${model.gaps?.status!=='complete'?`<p class="desk-notice">${model.gaps?.status==='incomplete'?`${missingDays(model.gaps.missingSessions?.length||0)} The line breaks at known gaps.`:'Calendar coverage is unknown. A continuous line does not prove that no trading days are missing.'}</p>`:''}${priceTable(points,currency,retained)}${comparisonView(model.comparison,symbol||model.symbol)}`:`<div class="desk-empty"><h3>${retained?'Retained price history unavailable':'No imported price history'}</h3><p>${retained?'A source-backed daily dataset is needed before this panel can show prices.':'Import a daily price file to see it here. It stays in this tab until you reload. Use Import daily price data below.'}</p></div>`}
      <details class="desk-disclosure" data-state-key="prices:provenance"><summary>Source, timing and adjustments</summary>${!model?'<p>Source details appear after you import a file for this company. Paper marks (the checked prices the journal uses to value practice trades) remain unavailable.</p>':`${rows([['Provider',source.provider||'Unavailable'],['Dataset',source.dataset||'Unavailable'],['Feed',source.feed||'Not specified'],['Price session',words(source.priceSession)],['Volume session',words(source.volumeSession)],['Symbol reference date',source.symbolAsOf||'Not specified'],['Captured at',stamp(source.capturedAt)],['Published at',stamp(source.publishedAt)],['Capture state',capture],['Trading-day coverage',session],['Expected latest trading day',freshness.expectedLatestSession||'Unavailable'],['Declared delay',Number.isFinite(freshness.declaredDelayMinutes)?`${freshness.declaredDelayMinutes} minute${freshness.declaredDelayMinutes===1?'':'s'}`:'Not specified'],['Price basis',basis(model?.priceBasis)],['Volume basis',words(model?.volumeBasis)],['Review state',words(model?.chartTrust)],['Paper marks','Unavailable']])}<p class="desk-source">${external(source.url,'Open data source')}</p>${model?.warnings?.length?`<ul>${model.warnings.map(item=>`<li>${escape(warning(item))}</li>`).join('')}</ul>`:''}${model?.issues?.length?`<ul>${model.issues.map(item=>`<li>${escape(words(item))}</li>`).join('')}</ul>`:''}`}</details>
      <details class="desk-disclosure" data-state-key="prices:import"><summary>Import daily price data</summary><p>Choose canonical Cribscore price JSON (up to 2 MiB), including source, capture time and adjustment basis. A valid import replaces all currently imported datasets. Data stays only in this tab and is cleared on reload. Keep your original file. Imported values do not become verified journal prices.</p><p>Canonical JSON is the exact file layout shown in the guide below.</p><p><a href="./help/price-import.html" target="_blank" rel="noopener noreferrer">JSON format guide and example<span class="sr-only"> (opens in a new tab)</span> <span aria-hidden="true">↗</span></a></p><form data-price-form="import" class="desk-form"><label for="price-import-file">Price file (JSON)<input id="price-import-file" name="file" type="file" accept=".json,application/json" required></label><button class="desk-button" type="submit">Import price data</button></form>${line(anchorOf('form','import'))}</details>
    </section>
    ${renderPriceSetup(priceSetup)}
  </div>`;
}
